        String stationCode,
        String stationName,
        String partyA,
        String partyB,
        Instant createdAt) {
}

package com.example.starter.web.dto;

import java.math.BigDecimal;
import java.time.LocalDate;

import jakarta.validation.constraints.DecimalMin;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;

/**
 * 日指定气量（能量）登记请求。
 *
 * @param stationCode 交接站编码
 * @param gasDay 气量日（UTC）
 * @param nominatedEnergyMj 日指定能量，单位 MJ
 * @param penaltyUnitPrice 超出免考区间的违约金单价，单位 元/MJ
 */
public record NominationRequest(
        @NotBlank String stationCode,
        @NotNull LocalDate gasDay,
        @NotNull @DecimalMin("0.001") BigDecimal nominatedEnergyMj,
        @NotNull @DecimalMin("0.0") BigDecimal penaltyUnitPrice) {
}

package com.example.starter.web.dto;

import java.math.BigDecimal;
import java.time.LocalDate;

/**
 * 日指定气量响应。
 */
public record NominationResponse(
        String stationCode,
        LocalDate gasDay,
        BigDecimal nominatedEnergyMj,
        BigDecimal penaltyUnitPrice) {
}

package com.example.starter.web.dto;

import java.math.BigDecimal;
import java.time.Instant;

import jakarta.validation.constraints.DecimalMin;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;

/**
 * 计量读数上报请求。按“交接站＋表底时刻”去重，允许乱序到达后归位。
 *
 * @param stationCode 交接站编码
 * @param meterId 流量计编号
 * @param readingTime 表底时刻（UTC）
 * @param meterIndex 该时刻累计表底（标况体积），单位 Nm3
 * @param heatingValue 该采样点热值，单位 MJ/Nm3
 */
public record ReadingRequest(
        @NotBlank String stationCode,
        @NotBlank String meterId,
        @NotNull Instant readingTime,
        @NotNull @DecimalMin("0.0") BigDecimal meterIndex,
        @NotNull @DecimalMin("0.0") BigDecimal heatingValue) {
}

package com.example.starter.web.dto;

import java.math.BigDecimal;
import java.time.Instant;

/**
 * 计量读数响应（按表底时刻升序归位）。
 */
public record ReadingResponse(
        Long id,
        String stationCode,
        String meterId,
        Instant readingTime,
        BigDecimal meterIndex,
        BigDecimal heatingValue,
        Instant receivedAt,
        boolean late) {
}

