    /** 按 requestId 查询。 */
    public Optional<DisputeRow> findByRequestId(String requestId) {
        return jdbc.query("SELECT * FROM dispute WHERE request_id = ?", ROW_MAPPER, requestId)
                .stream().findFirst();
