    }

    /** 交接方确认；同一事务内双方先后确认一致即生效，单方不生效。 */
    public VoucherResponse confirm(ConfirmRequest request) {
        throw new UnsupportedOperationException();
    }

    /** 发起争议：生效后 7 个自然日争议期内（含第 7 日）受理，逾期拒绝并封账。 */
    public VoucherResponse dispute(DisputeRequest request) {
